import { computed } from 'vue';
import { useTheme } from '../theme/index.js';

const props = defineProps({
  alt: {
    type: String,
    default: 'Subscription Lifecycle Supervisor Logo',
  },
  mode: {
    type: String,
    default: 'auto', // 'auto', 'light', or 'dark'
    validator: (val) => ['auto', 'light', 'dark'].includes(val),
  },
});

const { isLightTheme } = useTheme();

const effectiveTheme = computed(() => {
  if (props.mode === 'light') return 'light';
  if (props.mode === 'dark') return 'dark';
  return isLightTheme.value ? 'light' : 'dark';
});

const colors = computed(() => {
  if (effectiveTheme.value === 'light') {
    return {
      begeFill: '#F6F3EE',      // Bege
      blackOutline: '#070908',  // Preto
      greenAccent: '#23dfa0',   // Verde
    };
  }
  return {
    begeFill: '#070908',      // Preto no dark mode
    blackOutline: '#23dfa0',  // Verde no dark mode
    greenAccent: '#F6F3EE',   // Bege no dark mode
  };
});
